import React, { useState, useEffect } from 'react';

const Feedback = () => {
  const [monuments, setMonuments] = useState([]);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    monument_id: '',
    rating: 5,
    message: '',
  });
  const [submitted, setSubmitted] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchMonuments();
  }, []);

  const fetchMonuments = async () => {
    try {
      // In production, replace with actual API call
      // const response = await fetch('http://localhost:8000/api/monuments');
      // const data = await response.json();

      // Mock data
      const mockMonuments = [
        { id: 1, title: 'Taj Mahal' },
        { id: 2, title: 'Great Wall of China' },
        { id: 3, title: 'Colosseum' },
        { id: 4, title: 'Machu Picchu' },
        { id: 5, title: 'Petra' },
      ];

      setMonuments(mockMonuments);
    } catch (error) {
      console.error('Error fetching monuments:', error);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      // In production, send to API
      // await fetch('http://localhost:8000/api/feedback', {
      //   method: 'POST',
      //   headers: { 'Content-Type': 'application/json' },
      //   body: JSON.stringify(formData),
      // });

      console.log('Feedback submitted:', formData);
      setSubmitted(true);

      setTimeout(() => {
        setSubmitted(false);
        setFormData({
          name: '',
          email: '',
          monument_id: '',
          rating: 5,
          message: '',
        });
      }, 3000);
    } catch (error) {
      console.error('Error submitting feedback:', error);
    } finally {
      setLoading(false);
    }
  };

  const ratings = [
    { value: 5, label: 'Excellent', emoji: '⭐⭐⭐⭐⭐' },
    { value: 4, label: 'Very Good', emoji: '⭐⭐⭐⭐' },
    { value: 3, label: 'Good', emoji: '⭐⭐⭐' },
    { value: 2, label: 'Fair', emoji: '⭐⭐' },
    { value: 1, label: 'Poor', emoji: '⭐' },
  ];

  return (
    <div className="min-h-screen pt-20">
      {/* Header */}
      <section className="bg-gradient-to-r from-primary-600 to-primary-800 text-white py-16">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <h1 className="text-4xl md:text-5xl font-bold mb-4">Share Your Feedback</h1>
          <p className="text-xl text-primary-100">
            We value your opinion. Tell us about your experience with our heritage sites
          </p>
        </div>
      </section>

      {/* Feedback Form */}
      <section className="py-16">
        <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="bg-white rounded-xl shadow-2xl p-8 md:p-12">
            {submitted && (
              <div className="mb-8 p-6 bg-green-50 border-2 border-green-200 rounded-xl">
                <div className="flex items-center">
                  <svg className="w-6 h-6 text-green-600 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                  <div>
                    <p className="text-green-800 font-bold text-lg">Thank you for your feedback!</p>
                    <p className="text-green-700">Your response has been recorded successfully.</p>
                  </div>
                </div>
              </div>
            )}

            <form onSubmit={handleSubmit}>
              {/* Name */}
              <div className="mb-6">
                <label htmlFor="name" className="block text-gray-700 font-semibold mb-2">
                  Your Name
                </label>
                <input
                  type="text"
                  id="name"
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  required
                  className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500 transition-all"
                  placeholder="Enter your full name"
                />
              </div>

              {/* Email */}
              <div className="mb-6">
                <label htmlFor="email" className="block text-gray-700 font-semibold mb-2">
                  Email Address
                </label>
                <input
                  type="email"
                  id="email"
                  name="email"
                  value={formData.email}
                  onChange={handleChange}
                  required
                  className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500 transition-all"
                  placeholder="your.email@example.com"
                />
              </div>

              {/* Monument Selection */}
              <div className="mb-6">
                <label htmlFor="monument_id" className="block text-gray-700 font-semibold mb-2">
                  Select Monument (Optional)
                </label>
                <select
                  id="monument_id"
                  name="monument_id"
                  value={formData.monument_id}
                  onChange={handleChange}
                  className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500 transition-all"
                >
                  <option value="">General Feedback</option>
                  {monuments.map((monument) => (
                    <option key={monument.id} value={monument.id}>
                      {monument.title}
                    </option>
                  ))}
                </select>
              </div>

              {/* Rating */}
              <div className="mb-6">
                <label className="block text-gray-700 font-semibold mb-3">
                  Your Rating
                </label>
                <div className="grid grid-cols-1 sm:grid-cols-5 gap-3">
                  {ratings.map((rating) => (
                    <label
                      key={rating.value}
                      className={`cursor-pointer p-4 border-2 rounded-lg text-center transition-all ${
                        formData.rating === rating.value
                          ? 'border-primary-600 bg-primary-50'
                          : 'border-gray-300 hover:border-primary-300'
                      }`}
                    >
                      <input
                        type="radio"
                        name="rating"
                        value={rating.value}
                        checked={formData.rating === rating.value}
                        onChange={handleChange}
                        className="sr-only"
                      />
                      <div className="text-2xl mb-1">{rating.emoji}</div>
                      <div className="text-sm font-medium text-gray-700">{rating.label}</div>
                    </label>
                  ))}
                </div>
              </div>

              {/* Message */}
              <div className="mb-8">
                <label htmlFor="message" className="block text-gray-700 font-semibold mb-2">
                  Your Feedback
                </label>
                <textarea
                  id="message"
                  name="message"
                  value={formData.message}
                  onChange={handleChange}
                  required
                  rows="6"
                  className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500 transition-all resize-none"
                  placeholder="Share your thoughts, experiences, or suggestions..."
                ></textarea>
                <p className="mt-2 text-sm text-gray-500">
                  {formData.message.length} / 1000 characters
                </p>
              </div>

              {/* Submit Button */}
              <button
                type="submit"
                disabled={loading}
                className={`w-full py-4 px-6 rounded-lg font-bold text-lg transition-all duration-300 ${
                  loading
                    ? 'bg-gray-400 cursor-not-allowed'
                    : 'bg-primary-600 hover:bg-primary-700 transform hover:scale-105 shadow-lg'
                } text-white`}
              >
                {loading ? (
                  <span className="flex items-center justify-center">
                    <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    Submitting...
                  </span>
                ) : (
                  'Submit Feedback'
                )}
              </button>
            </form>
          </div>

          {/* Info Section */}
          <div className="mt-12 grid md:grid-cols-3 gap-6">
            <div className="bg-white rounded-xl shadow-lg p-6 text-center">
              <div className="w-12 h-12 bg-primary-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <svg className="w-6 h-6 text-primary-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                </svg>
              </div>
              <h3 className="font-bold text-gray-900 mb-2">Secure</h3>
              <p className="text-sm text-gray-600">Your information is safe with us</p>
            </div>

            <div className="bg-white rounded-xl shadow-lg p-6 text-center">
              <div className="w-12 h-12 bg-primary-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <svg className="w-6 h-6 text-primary-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                </svg>
              </div>
              <h3 className="font-bold text-gray-900 mb-2">Fast</h3>
              <p className="text-sm text-gray-600">Quick and easy submission</p>
            </div>

            <div className="bg-white rounded-xl shadow-lg p-6 text-center">
              <div className="w-12 h-12 bg-primary-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <svg className="w-6 h-6 text-primary-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 8h10M7 12h4m1 8l-4-4H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-3l-4 4z" />
                </svg>
              </div>
              <h3 className="font-bold text-gray-900 mb-2">Valued</h3>
              <p className="text-sm text-gray-600">We read every feedback</p>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Feedback;
